window.VZOROVA_ZKOUSKA = {"sada":"cvicna-4","oficialni":false,"otazky":[{"id":"UP-2-02","n":1,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"<p>Co je kvalita?<\/p>","m":["Činnosti zaměřené na poskytnutí důvěry, že požadavky na kvalitu budou splněny.","Celkové náklady na činnosti související s kvalitou, tj. náklady na prevenci, hodnocení a interní a externí selhání.","Stupeň, do jakého komponenta nebo systém chrání informace a data podle úrovně oprávnění osob či systémů.","Stupeň, do jakého pracovní produkt splňuje stanovené i implicitní potřeby svých zainteresovaných stran."],"ok":[3],"vys":{"a":"Není správně. Toto je definice zajištění kvality (QA).","b":"Není správně. Toto je definice nákladů na kvalitu.","c":"Není správně. Toto je definice zabezpečení (security).","d":"Je správně. Toto je definice kvality podle slovníku ISTQB."},"obecne":"Podle slovníku ISTQB je kvalita stupeň, do jakého pracovní produkt splňuje stanovené i implicitní potřeby svých zainteresovaných stran. Testování (sylabus 1.2) je jedním ze způsobů řízení kvality.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"UP-1-08","n":2,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností je přínosem týmového přístupu?<\/p>","m":["<p>Kolektivní odpovědnost všech za výsledek<\/p>","<p>Snížená týmová synergie<\/p>","<p>Omezená flexibilita při přidělování úkolů<\/p>","<p>Omezená komunikace mezi členy týmu<\/p>"],"ok":[0],"vys":{"a":"Je správně. Při týmovém přístupu je každý člen týmu zodpovědný za kvalitu – odpovědnost je kolektivní.","b":"Není správně. Týmový přístup synergii naopak vytváří.","c":"Není správně. Při týmovém přístupu může každý člen týmu s potřebnými dovednostmi vykonávat jakýkoliv úkol, flexibilita tedy roste.","d":"Není správně. Týmový přístup komunikaci a spolupráci v týmu naopak zlepšuje."},"obecne":"Sylabus 1.5.2: Při týmovém přístupu je každý člen týmu zodpovědný za kvalitu. Týmový přístup zvyšuje týmovou dynamiku, zlepšuje komunikaci a spolupráci a vytváří synergii. Ostatní možnosti popisují opak těchto přínosů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UC-1-07","n":3,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Vývojář pracuje na nové funkci webové aplikace, která uživatelům umožňuje nahrávat do aplikace obrázky. Vývojář napíše kód pro nahrávání obrázků, ale zapomene doplnit kód, který kontroluje velikost obrázků. V důsledku toho mohou uživatelé nahrát příliš velké obrázky, což způsobí pád aplikace. Co z následujícího je chyba?<\/p>","m":["<p>Vývojář zapomněl doplnit kód pro kontrolu velikosti obrázku.<\/p>","<p>Pád aplikace.<\/p>","<p>Uživatelé nahrávají obrázky ve velikosti, kterou web nepodporuje.<\/p>","<p>Žádná z uvedených možností.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Chyba (omyl) je lidské jednání – vývojář zapomněl doplnit kontrolu velikosti obrázku, čímž vznikl defekt v kódu.","b":"Není správně. Pád aplikace je selhání, tedy projev defektu při spuštění.","c":"Není správně. Nahrávání velkých obrázků je podmínka, za které se defekt projeví, nikoli chyba.","d":"Není správně. Chybou je opomenutí vývojáře v možnosti a."},"obecne":"Sylabus 1.2.3: Lidé dělají chyby (omyly), v jejichž důsledku vznikají defekty, které mohou při spuštění vést k selhání. Zde je chybou opomenutí vývojáře, defektem chybějící kontrola velikosti v kódu a selháním pád aplikace.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UP-3-03","n":4,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Vlastník produktu (product owner) prohlásí, že vaší rolí testera v agilním týmu je zachytit všechny defekty před koncem každé iterace. Který z následujících principů testování můžete NEJLÉPE použít jako odpověď na toto tvrzení?","m":["Většinu defektů obvykle obsahuje malé množství komponent systému.","Ani odstranění všech nalezených defektů nezaručí úspěch systému.","Testování může prokázat přítomnost defektů, ale ne jejich nepřítomnost.","Defekty odstraněné v rané fázi nezpůsobí další defekty v odvozených produktech."],"ok":[2],"vys":{"a":"Není správně. Princip shlukování defektů říká, kde se defekty nejspíše nacházejí, ne zda lze najít všechny.","b":"Není správně. Princip Nepřítomnost defektů je klam se týká toho, že ani bezchybný systém nemusí splnit potřeby uživatelů, což vlastník produktu nepožaduje.","c":"Je správně. Testování nemůže prokázat, že žádné defekty nezůstaly, proto nelze slíbit zachycení všech defektů.","d":"Není správně. Princip Včasné testování šetří čas a peníze neodpovídá na požadavek najít všechny defekty."},"obecne":"Sylabus 1.3, princip 1: Testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost. Testování snižuje pravděpodobnost, že v testovaném objektu zůstaly neodhalené defekty, ale nemůže prokázat, že v něm žádné nejsou. Požadavek zachytit všechny defekty je proto nesplnitelný.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-2-04","n":5,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Následující tvrzení se týkají činností, které jsou součástí procesu testování:<\/p><p>(i) Identifikace testovacích dat potřebných pro testovací podmínky a testovací případy<br>(ii) Vytváření automatizovaných testovacích skriptů<br>(iii) Návrh testovacího prostředí<br>(iv) Vytváření a prioritizace testovacích procedur<br>(v) Ověření, že je testovací prostředí správně nastaveno<\/p><p>Které z následujících tvrzení je PRAVDIVÉ?<\/p>","m":["(i) a (ii) jsou součástí návrhu testů, (iii), (iv) a (v) jsou součástí implementace testování.","(i) a (v) jsou součástí návrhu testů, (ii), (iii) a (iv) jsou součástí implementace testování.","(i) a (iv) jsou součástí návrhu testů, (ii), (iii) a (v) jsou součástí implementace testování.","(i) a (iii) jsou součástí návrhu testů, (ii), (iv) a (v) jsou součástí implementace testování."],"ok":[3],"vys":{"a":"Není správně. Vytváření automatizovaných testovacích skriptů patří do implementace testování, návrh testovacího prostředí do návrhu testů.","b":"Není správně. Ověření nastavení prostředí patří do implementace, návrh prostředí do návrhu testů.","c":"Není správně. Vytváření a prioritizace testovacích procedur patří do implementace testování.","d":"Je správně. Požadavky na testovací data a návrh testovacího prostředí patří do návrhu testů; skripty, testovací procedury a ověření prostředí do implementace testování."},"obecne":"Sylabus 1.4.1: Návrh testů zahrnuje stanovení požadavků na testovací data a návrh testovacího prostředí. Implementace testování zahrnuje vytvoření testovacích procedur a jejich prioritizaci v harmonogramu, vytvoření manuálních a automatizovaných testovacích skriptů a sestavení testovacího prostředí včetně ověření jeho správného nastavení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UC-4-62","n":6,"lo":"FL-1.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Pracujete na kritickém projektu, který musí být dodán v napjatém termínu. Tým tvoří vysoce kvalifikovaní odborníci, včetně seniorního testera s rozsáhlými zkušenostmi s testováním a dobrou znalostí byznysové domény. Kvůli velkému časovému omezení musí být testování účinné i efektivní.<\/p><p>Jaký způsob definování testovacích procedur je v této situaci NEJVHODNĚJŠÍ?<\/p>","m":["<p>Přehled testovacích podmínek a obecných kroků na vysoké úrovni<\/p>","<p>Podrobné rozepsání každého kroku testu včetně očekávaných výsledků<\/p>","<p>Úplná dokumentace všech testovacích případů a záznam každého kroku<\/p>","<p>Odvození všech testů formálními technikami a jejich podrobná specifikace<\/p>"],"ok":[0],"vys":{"a":"Je správně. Zkušený tester se znalostí domény nepotřebuje podrobný návod; stručný přehled šetří čas a ponechává prostor pro jeho úsudek.","b":"Není správně. Podrobné rozepisování kroků je časově náročné a u zkušeného testera v napjatém termínu zbytečné.","c":"Není správně. Úplná dokumentace a záznam každého kroku jsou v napjatém termínu neefektivní.","d":"Není správně. Podrobná specifikace všech testů je časově náročná a nevyužívá zkušenosti testera."},"obecne":"Sylabus 1.4.2: proces testování závisí na kontextu – mimo jiné na dovednostech, znalostech a zkušenostech členů týmu a na omezeních projektu (např. čas). Tyto faktory ovlivňují i úroveň podrobnosti testwaru. Seniornímu testerovi s doménovou znalostí v napjatém termínu nejlépe poslouží přehled testovacích podmínek a obecných kroků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"}},{"id":"UC-1-03","n":7,"lo":"FL-1.4.4","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností NENÍ přínosem dobré trasovatelnosti?","m":["Usnadňuje určení dopadu změn.","Zaručuje, že testovací případy neobsahují žádné defekty.","Pomáhá ověřit, že všechny požadavky jsou pokryty testy.","Usnadňuje komunikaci výsledků testování se zainteresovanými stranami."],"ok":[1],"vys":{"a":"Není správně. Určení dopadu změn je jedním z přínosů trasovatelnosti.","b":"Je správně. Trasovatelnost propojuje položky testovací báze s testwarem, ale nijak nezaručuje bezchybnost testovacích případů.","c":"Není správně. Trasovatelnost mezi testovacími případy a požadavky pomáhá ověřit pokrytí požadavků.","d":"Není správně. Trasovatelnost zlepšuje srozumitelnost reportů a komunikaci se zainteresovanými stranami."},"obecne":"Sylabus 1.4.4: Dobrá trasovatelnost umožňuje vyhodnocovat pokrytí, určit dopad změn, usnadňuje audit a zlepšuje srozumitelnost reportů a komunikaci se zainteresovanými stranami. O kvalitě samotných testovacích případů nic nezaručuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"}},{"id":"UP-1-07","n":8,"lo":"FL-1.5.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících dovedností je pro testera NEJCENNĚJŠÍ v kontextu analýzy složitých softwarových požadavků?<\/p>","m":["<p>Zběhlost v používání nástrojů pro management testování k organizaci testovacích případů.<\/p>","<p>Znalost různých metodik vývoje softwaru, jako je agilní vývoj a vodopád.<\/p>","<p>Analytické a kritické myšlení, které umožní odhalit nejasnosti a nekonzistence.<\/p>","<p>Schopnost efektivně spolupracovat s vývojáři a byznys analytiky.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Práce s nástroji pro management testování pomáhá testovací případy organizovat, ale k pochopení a posouzení složitých požadavků nepřispívá.","b":"Není správně. Znalost metodik vývoje poskytuje kontext, ale pro analýzu konkrétních složitých požadavků není rozhodující.","c":"Je správně. Analytické a kritické myšlení (sylabus 1.5.1) umožňuje složitým požadavkům porozumět, najít v nich nejasnosti, nekonzistence a defekty a odvodit z nich testovací podmínky.","d":"Není správně. Spolupráce je důležitá pro získávání informací a vyjasňování požadavků, samotnou analýzu požadavků však nenahradí."},"obecne":"Sylabus 1.5.1 uvádí mezi obecnými dovednostmi testera analytické a kritické myšlení a kreativitu. Při analýze složitých požadavků jsou právě analytické dovednosti klíčové pro jejich pochopení, nalezení nejasností a defektů a odvození testovacích podmínek.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"}},{"id":"UP-6-09","n":9,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Který osvědčený postup zajišťuje, že testování je přiměřeně důkladné a zároveň se mezi úrovněmi testování zbytečně nepřekrývá?<\/p>","m":["<p>Automatizovat všechny testovací činnosti ve všech úrovních<\/p>","<p>Ve vyšších úrovních testování používat pouze manuální testy<\/p>","<p>Spouštět stejnou sadu testů ve všech úrovních testování<\/p>","<p>Stanovit pro každou úroveň specifické a odlišné cíle testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Automatizace zvyšuje efektivitu, ale nezajišťuje, aby se úrovně testování nepřekrývaly.","b":"Není správně. Volba manuálních testů nemá vliv na překrývání úrovní testování.","c":"Není správně. Opakování stejných testů ve všech úrovních by vedlo právě k nadbytečnosti.","d":"Je správně. Specifické a odlišné cíle jednotlivých úrovní zajišťují přiměřenou důkladnost bez nadbytečnosti."},"obecne":"Sylabus 2.1.2: existují různé úrovně testování a každá má své specifické (a někdy i odlišné) cíle. Díky tomu je testování přiměřeně detailní a zároveň nedochází k nadbytečnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-5-11","n":10,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje vývoj řízený chováním (BDD)?<\/p>","m":["<p>BDD podporuje spolupráci vývojářů, testerů a zástupců byznysu.<\/p>","<p>BDD spočívá v psaní testů komponent zaměřených výhradně na funkčnost kódu.<\/p>","<p>BDD při ověřování chování softwaru spoléhá na manuální testování.<\/p>","<p>BDD klade důraz na zápis akceptačních kritérií v technickém jazyce.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Společný popis chování v přirozeném jazyce usnadňuje spolupráci vývojářů, testerů a zástupců byznysu.","b":"Není správně. BDD popisuje požadované chování aplikace, nejde o testy komponent zaměřené jen na kód.","c":"Není správně. Testovací případy v BDD by se měly automaticky převádět na spustitelné testy.","d":"Není správně. V BDD se chování popisuje v přirozeném jazyce srozumitelném zainteresovaným stranám, ne v technickém jazyce."},"obecne":"Sylabus 2.1.3: v BDD je požadované chování aplikace popsáno testovacími případy v jednoduché formě přirozeného jazyka srozumitelného zainteresovaným stranám (obvykle Given/When/Then), které se poté automaticky převádějí na spustitelné testy. Společný jazyk podporuje spolupráci celého týmu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UC-2-19","n":11,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího je o principu shift left <strong>PRAVDIVÉ<\/strong>?<\/p>","m":["<p>Osvědčeným postupem v rámci principu shift left je psát testovací případy až po napsání kódu, aby se zvýšilo pokrytí.<\/p>","<p>Osvědčeným postupem v rámci principu shift left je psát testovací případy před napsáním kódu a během implementace spouštět kód v sadě testovacího vybavení (test harness).<\/p>","<p>Při uplatnění principu shift left se testuje dříve, takže testování v pozdějších fázích SDLC je zanedbáváno.<\/p>","<p>Princip shift left sice z dlouhodobého hlediska šetří pracnost, ale v pozdějších fázích procesu se očekává, že bude značně nákladný.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Shift left doporučuje psát testovací případy před kódem.","b":"Je správně. Psaní testovacích případů před kódem a spouštění kódu v sadě testovacího vybavení během implementace je příkladem shift left.","c":"Není správně. Shift left neznamená, že by se testování v pozdějších fázích mělo zanedbávat.","d":"Není správně. Shift left může být nákladnější na začátku, v pozdějších fázích ale pracnost a náklady šetří."},"obecne":"Sylabus 2.1.5: shift left (princip včasného testování) znamená provádět testování dříve v SDLC, např. nečekat na implementaci kódu nebo integraci komponent. Neznamená to, že by se testování v pozdějších fázích mělo zanedbávat. Zavedení může zpočátku znamenat vyšší náklady, ale v pozdějších fázích pracnost a náklady šetří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UC-2-06","n":12,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o retrospektivách je <strong>PRAVDIVÉ<\/strong>?<\/p>","m":["<p>Hlavním účelem retrospektivy je najít viníka nedostatků projektu.<\/p>","<p>Retrospektivy se konají jen na začátku projektu, před první iterací.<\/p>","<p>Retrospektivy se konají např. na konci iterace nebo po dosažení milníku.<\/p>","<p>Retrospektivy lze použít pouze v agilních modelech SDLC.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Retrospektiva slouží ke zlepšování procesu, ne k hledání viníků.","b":"Není správně. Retrospektivy se konají na konci projektu či iterace, při dosažení milníku nebo dle potřeby.","c":"Je správně. Retrospektivy se často konají na konci projektu nebo iterace, při dosažení milníku nebo dle potřeby.","d":"Není správně. Načasování a organizace retrospektiv závisí na modelu SDLC, ale nejsou omezeny na agilní modely."},"obecne":"Sylabus 2.1.6: retrospektivy se často konají na konci projektu nebo iterace, při dosažení milníku nebo dle potřeby. Jejich načasování a organizace závisí na konkrétním modelu SDLC a slouží ke kontinuálnímu zlepšování procesu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UP-6-13","n":13,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Ve kterých úrovních testování lze provádět nefunkcionální testy?<\/p>","m":["<p>Pouze při integračním, systémovém a akceptačním testování<\/p>","<p>Pouze při systémovém testování<\/p>","<p>Pouze při testování komponent a integračním testování<\/p>","<p>Při testování komponent, integračním, systémovém i akceptačním testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Nefunkcionální testy lze provádět i při testování komponent (např. výkonnost komponenty).","b":"Není správně. Nefunkcionální testy lze provádět i v jiných úrovních, např. už při testování komponent.","c":"Není správně. Nefunkcionální testy se neomezují na nižší úrovně testování.","d":"Je správně. Všechny typy testů včetně nefunkcionálních lze aplikovat ve všech úrovních testování."},"obecne":"Sylabus 2.2.2: všechny čtyři typy testů (funkcionální, nefunkcionální, černé a bílé skříňky) lze aplikovat ve všech úrovních testování, i když konkrétní zaměření se v každé úrovni liší. Nefunkcionální testování je někdy vhodné začít již v rané fázi, např. při testování komponent.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"TR-020","n":14,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá testování, které se provádí po opravě defektu a ověřuje, zda byl původní defekt úspěšně opraven?","m":["Konfirmační testování","Regresní testování","Testování údržby","Akceptační testování"],"ok":[0],"vys":{"a":"Je správně. Konfirmační testování potvrzuje, že byl původní defekt úspěšně opraven.","b":"Není správně. Regresní testování ověřuje, zda změna (včetně opravy) nezpůsobila nežádoucí dopady v jiných částech systému.","c":"Není správně. Testování údržby se týká změn systému, který je již v provozu; samo o sobě neoznačuje ověření konkrétní opravy.","d":"Není správně. Akceptační testování validuje připravenost systému k nasazení a splnění byznysových potřeb uživatele."},"obecne":"Sylabus 2.2.3: konfirmační testování potvrzuje, že byl původní defekt úspěšně opraven (např. opakovaným provedením testů, které dříve selhaly). Regresní testování naopak ověřuje, zda po změnách nedošlo k nežádoucím dopadům jinde.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"UP-1-15","n":15,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících pracovních produktů je vhodný pro posouzení pomocí statického testování?<\/p>","m":["<p>Systémové logy v reálném čase<\/p>","<p>Specifikace softwarových požadavků<\/p>","<p>Živá produkční databáze<\/p>","<p>Zašifrovaný zdrojový kód<\/p>"],"ok":[1],"vys":{"a":"Není správně. Systémové logy v reálném čase zachycují události za běhu systému; nejde o pracovní produkt, který se posuzuje statickým testováním.","b":"Je správně. Specifikace požadavků je typickým pracovním produktem pro revize, které odhalí nejednoznačnosti nebo nekonzistence v rané fázi SDLC.","c":"Není správně. Živá produkční databáze obsahuje provozní data, nejde o pracovní produkt vhodný pro statické testování.","d":"Není správně. Zašifrovaný zdrojový kód není pro člověka čitelný a nelze jej revidovat ani běžně staticky analyzovat."},"obecne":"Sylabus 3.1.1: téměř každý pracovní produkt může být prozkoumán statickým testováním, např. specifikace požadavků, zdrojový kód, plány testování nebo testovací případy. Revizi lze použít na jakýkoli pracovní produkt, který lze přečíst a porozumět mu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UP-2-18","n":16,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících bodů jsou faktory úspěchu revizí?<\/p><p>I. Jsou definovány jasné cíle a měřitelná výstupní kritéria.<\/p><p>II. Účastníci mají na přípravu revize dostatek času.<\/p><p>III. Revize jsou součástí firemní kultury.<\/p><p>IV. Výsledky revize slouží k hodnocení výkonu jejích účastníků.<\/p>","m":["<p>I a III<\/p>","<p>II, III a IV<\/p>","<p>I, II a III<\/p>","<p>IV<\/p>"],"ok":[2],"vys":{"a":"Není správně. Chybí bod II – dostatek času na přípravu je faktorem úspěchu.","b":"Není správně. Bod IV faktorem úspěchu není; hodnotí se pracovní produkt, ne účastníci.","c":"Je správně. Body I, II a III jsou faktory úspěchu podle sylabu.","d":"Není správně. Hodnocení účastníků revize je v rozporu s faktory úspěchu."},"obecne":"Sylabus 3.2.5 uvádí mezi faktory úspěchu jasné cíle a měřitelná výstupní kritéria (hodnocen je pracovní produkt, nikoli účastníci), dostatek času na přípravu a to, že revize jsou součástí firemní kultury. Bod IV je proto chybný.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UC-3-03","n":17,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Statické testování může být v životním cyklu vývoje softwaru (SDLC) cenným nástrojem. Co z následujícího je přínosem statického testování?<\/p>","m":["<p>Odhalování funkcionálních defektů uživatelského rozhraní za běhu<\/p>","<p>Měření výkonnosti aplikace za běhu<\/p>","<p>Testování interakce mezi integrovanými komponentami<\/p>","<p>Identifikace defektů v nespustitelných pracovních produktech<\/p>"],"ok":[3],"vys":{"a":"Není správně. Funkcionální defekty uživatelského rozhraní za běhu odhalí dynamické testování.","b":"Není správně. Výkonnost za běhu měří dynamické testování.","c":"Není správně. Interakci integrovaných komponent ověřuje dynamické integrační testování.","d":"Je správně. Statické testování může odhalit defekty v nespustitelných pracovních produktech, které dynamické testování zjistit nemůže."},"obecne":"Sylabus 3.1.2: statické testování může odhalit defekty v nejranějších fázích SDLC a také defekty, které nelze zjistit dynamickým testováním, např. nedosažitelný kód, chybně implementované návrhové vzory nebo defekty v nespustitelných pracovních produktech.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UP-2-17","n":18,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Autor kódu vede revizi svého kódu pro další vývojáře a testery. O jaký typ revize se jedná?<\/p>","m":["<p>Předvedení (walkthrough)<\/p>","<p>Neformální vývojářská revize<\/p>","<p>Audit<\/p>","<p>Inspekce<\/p>"],"ok":[0],"vys":{"a":"Je správně. Předvedení (walkthrough) je revize vedená autorem.","b":"Není správně. Neformální revize se neřídí definovaným procesem; vedení autorem je charakteristické pro předvedení.","c":"Není správně. Audit není typem revize uvedeným v sylabu a obvykle jej provádí nezávislá třetí strana.","d":"Není správně. Inspekci nesmí autor vést – nemůže v ní vystupovat jako vedoucí revize ani zapisovatel."},"obecne":"Sylabus 3.2.4: předvedení (walkthrough) je revize vedená autorem, která může sloužit např. k hodnocení kvality, vzdělávání revidujících a dosažení dohody.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UP-3-25","n":19,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Čím se liší testování bílé skříňky od testování černé skříňky?<\/p>","m":["<p>Testování bílé skříňky nevyžaduje znalost vnitřního kódu, zatímco testování černé skříňky silně spoléhá na porozumění vnitřní implementaci.<\/p>","<p>Testování bílé skříňky vychází z vnitřní struktury a logiky kódu, zatímco testování černé skříňky se zaměřuje na vnější chování.<\/p>","<p>Testování bílé skříňky se vztahuje pouze na požadavky vysoké úrovně, zatímco testování černé skříňky se zaměřuje na specifikace nízké úrovně.<\/p>","<p>Testování bílé skříňky je vhodnější pro dynamické testování, zatímco testování černé skříňky se používá především pro statické testování.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Je to naopak: znalost vnitřní struktury vyžaduje testování bílé skříňky.","b":"Je správně. Techniky bílé skříňky vycházejí z vnitřní struktury a zpracování uvnitř testovaného objektu, techniky černé skříňky ze specifikovaného chování bez znalosti vnitřní struktury.","c":"Není správně. Obě kategorie technik lze použít na různých úrovních testování; rozdíl je ve zdroji testovacích případů, ne v úrovni požadavků.","d":"Není správně. Obě kategorie se používají při dynamickém testování a techniky bílé skříňky lze použít i při statickém testování."},"obecne":"<p>Sylabus 4.1: Techniky černé skříňky jsou založeny na analýze specifikovaného chování testovaného objektu bez informací o jeho vnitřní struktuře. Techniky bílé skříňky jsou založeny na analýze vnitřní struktury a zpracování uvnitř testovaného objektu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-31","n":20,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete systém vah, který určuje sazby za přepravu pro regionálního internetového distributora autodílů. Hmotnosti se zaokrouhlují na celé kilogramy. Sazby jsou určeny takto:<\/p><table><tr><th>Hmotnost zásilky<\/th><th>Sazba za přepravu<\/th><\/tr><tr><td>1 až 10 kg<\/td><td>sazba 1<\/td><\/tr><tr><td>11 až 25 kg<\/td><td>sazba 2<\/td><\/tr><tr><td>26 až 50 kg<\/td><td>sazba 3<\/td><\/tr><tr><td>51 kg a více<\/td><td>sazba 4<\/td><\/tr><\/table><p>Zásilky lehčí než 1 kg systém odmítne. Chcete seskupit testovací podmínky tak, abyste testování minimalizovali.<\/p><p>Kolik tříd ekvivalence (platných i neplatných) je pro hmotnost potřeba?<\/p>","m":["<p>4<\/p>","<p>6<\/p>","<p>5<\/p>","<p>8<\/p>"],"ok":[2],"vys":{"a":"Není správně. 4 třídy pokrývají jen platné hodnoty; chybí neplatná třída hmotností pod 1 kg.","b":"Není správně. 6 tříd by vyžadovalo i neplatnou třídu nad horní mezí, ta však neexistuje – třída „51 kg a více“ je shora neomezená.","c":"Je správně. Platné třídy jsou 1–10, 11–25, 26–50 a 51 kg a více, neplatná třída je méně než 1 kg – celkem 5 tříd.","d":"Není správně. 8 tříd by vyšlo např. při zdvojení tříd; tabulka definuje 4 platné třídy a existuje jediná neplatná třída."},"obecne":"Sylabus 4.2.1: rozdělení tříd ekvivalence dělí data do tříd, které testovaný objekt zpracovává stejně; uvažujeme platné i neplatné třídy. Zde jsou 4 platné třídy podle sazeb a 1 neplatná třída (méně než 1 kg). Poslední třída „51 kg a více“ nemá horní mez, takže další neplatná třída nevzniká.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-40","n":21,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Programátor validuje číselné pole s celými čísly takto: hodnoty menší než 10 jsou odmítnuty, hodnoty od 10 do 21 jsou přijaty, hodnoty větší nebo rovné 22 jsou odmítnuty.<\/p><p>Která z následujících sad vstupních hodnot pokrývá NEJVÍCE hraničních hodnot (dvouhodnotová analýza hraničních hodnot)?<\/p>","m":["<p>10, 11, 21, 22<\/p>","<p>9, 10, 11, 12<\/p>","<p>10, 11, 20, 21<\/p>","<p>9, 10, 21, 22<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pokrývá hraniční hodnoty 10, 21 a 22 (3 ze 4), chybí 9.","b":"Není správně. Pokrývá jen hraniční hodnoty 9 a 10 (2 ze 4).","c":"Není správně. Pokrývá jen hraniční hodnoty 10 a 21 (2 ze 4).","d":"Je správně. Pokrývá všechny čtyři hraniční hodnoty 9, 10, 21 a 22."},"obecne":"Sylabus 4.2.2: hraničními hodnotami jsou 9 (maximum třídy menší než 10), 10 a 21 (minimum a maximum platné třídy) a 22 (minimum třídy 22 a více). Všechny čtyři pokrývá pouze sada 9, 10, 21, 22.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-45","n":22,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Letecká společnost nabízí cestujícím povýšení do vyšší třídy podle této rozhodovací tabulky („–“ = akce není relevantní):<\/p><table><thead><tr><th><\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><th>Pravidlo 4<\/th><\/tr><\/thead><tbody><tr><td><strong>Podmínky<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Člen věrnostního programu<\/td><td>Ano<\/td><td>Ano<\/td><td>Ne<\/td><td>Ne<\/td><\/tr><tr><td>Cestovní třída<\/td><td>Business<\/td><td>Ekonomická<\/td><td>Business<\/td><td>Ekonomická<\/td><\/tr><tr><td><strong>Akce<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Povýšit do první třídy<\/td><td>Ano<\/td><td>Ne<\/td><td>Ne<\/td><td>Ne<\/td><\/tr><tr><td>Povýšit do business třídy<\/td><td>–<\/td><td>Ano<\/td><td>–<\/td><td>Ne<\/td><\/tr><\/tbody><\/table><p>Jaký je očekávaný výsledek pro každý z následujících testovacích případů?<\/p><p>1 – Člen věrnostního programu, který cestuje v business třídě<\/p><p>2 – Cestující, který není členem věrnostního programu a cestuje v ekonomické třídě<\/p>","m":["<p>1 – povýšit do první třídy; 2 – žádné povýšení nenabízet<\/p>","<p>1 – povýšit do první třídy; 2 – povýšit do business třídy<\/p>","<p>1 – žádné povýšení nenabízet; 2 – žádné povýšení nenabízet<\/p>","<p>1 – žádné povýšení nenabízet; 2 – povýšit do business třídy<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testovací případ 1 (člen, business) odpovídá pravidlu 1 – povýšit do první třídy; testovací případ 2 (nečlen, ekonomická) odpovídá pravidlu 4 – žádné povýšení.","b":"Není správně. Testovací případ 2 odpovídá pravidlu 4, podle kterého se povýšení do business třídy nenabízí.","c":"Není správně. Testovací případ 1 odpovídá pravidlu 1, podle kterého se nabízí povýšení do první třídy.","d":"Není správně. Testovací případ 1 odpovídá pravidlu 1 (povýšení do první třídy) a testovací případ 2 pravidlu 4, které žádné povýšení nenabízí."},"obecne":"<p>Sylabus 4.2.3: každý sloupec rozhodovací tabulky je pravidlo, které pro jednu kombinaci podmínek určuje akce. Testovací případ 1 (člen věrnostního programu, business třída) odpovídá pravidlu 1, testovací případ 2 (nečlen, ekonomická třída) pravidlu 4.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UC-4-22","n":23,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový diagram systému obsahuje právě těchto 5 platných přechodů:<\/p><table><tr><th>Ze stavu<\/th><th>Do stavu<\/th><\/tr><tr><td>S1<\/td><td>S2<\/td><\/tr><tr><td>S1<\/td><td>S5<\/td><\/tr><tr><td>S5<\/td><td>S1<\/td><\/tr><tr><td>S2<\/td><td>S3<\/td><\/tr><tr><td>S2<\/td><td>S4<\/td><\/tr><\/table><p>Stavy S3 a S4 jsou koncové (nevede z nich žádný přechod). Testovací případ může začínat v libovolném stavu a končí v koncovém stavu.<\/p><p>Které z následujících tvrzení je PRAVDIVÉ?<\/p>","m":["<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech stavů je 2 při začátku ve stavu S2.<\/p>","<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech platných přechodů je 2 při začátku ve stavu S1.<\/p>","<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech platných přechodů je 2 při začátku ve stavu S2.<\/p>","<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech platných přechodů je 1 při začátku ve stavu S1.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Ze stavu S2 nelze dosáhnout stavů S1 a S5, takže pokrytí všech stavů při začátku v S2 dosáhnout nelze.","b":"Je správně. Např. S1→S5→S1→S2→S4 a S1→S2→S3 pokryjí všech 5 platných přechodů; méně případů nestačí, protože existují dva koncové stavy.","c":"Není správně. Ze stavu S2 se nelze dostat do S1 ani S5, přechody S1→S2, S1→S5 a S5→S1 by zůstaly nepokryté.","d":"Není správně. Stavy S3 a S4 jsou koncové, jeden testovací případ proto nemůže pokrýt oba přechody S2→S3 i S2→S4."},"obecne":"Sylabus 4.2.4: při pokrytí platných přechodů musí testovací případy provést každý platný přechod. Začneme-li v S1, stačí dva případy (S1→S5→S1→S2→S4 a S1→S2→S3). Jeden případ nestačí, protože S3 a S4 jsou koncové stavy; ze stavu S2 se nelze vrátit do S1 ani S5.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-3-19","n":24,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Vyvíjený systém obsahuje složité výpočty a rozhodovací logiku. Je hodnocen jako vysoce rizikový, protože vývojový tým nemá v dané aplikační doméně mnoho zkušeností. Která z následujících technik testování by byla NEJVHODNĚJŠÍ pro testování komponent?<\/p>","m":["<p>Rozdělení tříd ekvivalence<\/p>","<p>Testování příkazů<\/p>","<p>Testování větví<\/p>","<p>Testování přechodů stavů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Rozdělení tříd ekvivalence je technika černé skříňky, nepracuje s rozhodovací logikou v kódu a při vysokém riziku samo o sobě nestačí.","b":"Není správně. 100% pokrytí příkazů nezaručuje otestování veškeré rozhodovací logiky.","c":"Je správně. Testování větví prověří všechny výsledky rozhodovací logiky v kódu a je silnější než testování příkazů.","d":"Není správně. Zadání nezmiňuje žádné stavy ani přechody mezi nimi."},"obecne":"<p>Sylabus 4.3.1 a 4.3.2: Testování větví pokryje všechny podmíněné a nepodmíněné větve, a tedy i rozhodovací logiku; 100% pokrytí větví zaručuje i 100% pokrytí příkazů. Pro rizikovou komponentu se složitou rozhodovací logikou je proto nejvhodnější.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-5-25","n":25,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o testování bílé skříňky je PRAVDIVÉ?<\/p>","m":["<p>Testování bílé skříňky se používá především k validaci vnějšího chování systému.<\/p>","<p>Testování bílé skříňky se opírá výhradně o analýzu externích specifikací.<\/p>","<p>Techniky testování bílé skříňky nejsou použitelné při statickém testování.<\/p>","<p>Testování bílé skříňky dokáže identifikovat defekty v kódu i bez podrobné dokumentace požadavků.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Vnější chování systému se ověřuje především technikami černé skříňky.","b":"Není správně. Testování bílé skříňky vychází z vnitřní struktury kódu, ne z externích specifikací.","c":"Není správně. Techniky bílé skříňky lze použít i při statickém testování, např. při revizi kódu nebo „běhu nanečisto“.","d":"Je správně. Testování bílé skříňky zohledňuje samotnou implementaci, proto odhalí defekty i tehdy, když je specifikace vágní, zastaralá nebo neúplná."},"obecne":"<p>Sylabus 4.3.3: Silnou stránkou technik bílé skříňky je, že zohledňují samotnou implementaci softwaru, což usnadňuje detekci defektů v případech, kdy je specifikace vágní, zastaralá nebo neúplná. Lze je použít i při statickém testování.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"UC-4-59","n":26,"lo":"FL-4.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících přístupů k testování je NEJVHODNĚJŠÍ v situaci, kdy je specifikace nekvalitní a na testování je velký časový tlak?<\/p>","m":["<p>Průzkumné testování<\/p>","<p>Testování případů užití<\/p>","<p>Pokrytí podmínek<\/p>","<p>Testování cest<\/p>"],"ok":[0],"vys":{"a":"Je správně. Průzkumné testování je nejužitečnější, když je specifikace nedostatečná nebo chybí a když je na testování výrazný časový tlak.","b":"Není správně. Testování případů užití vyžaduje kvalitní případy užití jako testovací bázi.","c":"Není správně. Pokrytí podmínek je technika bílé skříňky náročná na čas a sylabus CTFL ji nepopisuje.","d":"Není správně. Testování cest je pracná technika bílé skříňky, kterou sylabus CTFL nepopisuje."},"obecne":"<p><strong>Podle sylabu (kap. 4.4.2):<\/strong> <strong>Průzkumné testování je nejvíce užitečné v případech, kdy je specifikace nedostatečná nebo úplně chybí, taktéž je vhodnou metodou v případě výrazného časového tlaku na testování.<\/strong> Je také užitečné jako doplněk jiných (formálnějších) testovacích technik. Obecně bude účinnější v případech, kdy jsou testeři zkušení, mají znalosti z dané domény a vysokou úroveň základních dovedností jako jsou analytické schopnosti, zvídavost a kreativita.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"}},{"id":"UP-1-26","n":27,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Skupina zajištění kvality strávila poslední měsíc procházením systému pro management defektů a sestavila seznam všech selhání nahlášených při testování i v produkčním provozu. Seznam předala testovacímu týmu, který podle něj bude navrhovat testy pro příští vydání. Která z následujících technik testování NEJLÉPE odpovídá tomuto využití seznamu?<\/p>","m":["<p>Průzkumné testování<\/p>","<p>Útok na vady<\/p>","<p>Testování založené na kontrolních seznamech<\/p>","<p>Testování dle rozhodovací tabulky<\/p>"],"ok":[1],"vys":{"a":"Není správně. Při průzkumném testování se testy navrhují, provádějí a vyhodnocují souběžně s poznáváním testovaného objektu, ne podle předem získaného seznamu selhání.","b":"Je správně. Útok na vady vyžaduje vytvořit nebo získat seznam možných chyb, defektů a selhání (např. z údajů o defektech) a navrhnout testy, které je odhalí nebo vyvolají.","c":"Není správně. Kontrolní seznam obsahuje testovací podmínky, které se ověřují; zde jde o seznam selhání, na která se testy cíleně zaměří.","d":"Není správně. Testování dle rozhodovací tabulky je technika černé skříňky vycházející z kombinací podmínek ve specifikaci."},"obecne":"<p>Sylabus 4.4.1: Útok na vady je příkladem implementace odhadování chyb. Testeři vytvoří nebo získají seznam možných chyb, defektů a selhání – na základě zkušeností, údajů o defektech a selháních nebo obecných znalostí – a navrhnou testy, které je identifikují, odhalí nebo způsobí.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UC-1-39","n":28,"lo":"FL-4.5.1","k":"K2","k3":true,"vyber":1,"q":"Který z následujících je správný formát zápisu uživatelského scénáře?","m":["Všechny požadavky musí dodržovat byznysové pravidlo č. 17","Za předpokladu &lt;kontext&gt;, když &lt;událost&gt;, pak &lt;výsledek&gt;","Jako &lt;role&gt; chci &lt;cíl&gt;, abych &lt;přínos&gt;","Uživatel se může přihlásit přes Facebook nebo Google"],"ok":[2],"vys":{"a":"Není správně. Jde o byznysové pravidlo, nikoli o uživatelský scénář.","b":"Není správně. Formát kontext–událost–výsledek (Given/When/Then) se používá pro akceptační kritéria orientovaná na scénáře, ne pro samotný uživatelský scénář.","c":"Je správně. Toto je nejběžnější formát uživatelského scénáře podle sylabu.","d":"Není správně. Jde o obecný požadavek bez role a přínosu."},"obecne":"Sylabus 4.5.1: Nejběžnějším formátem uživatelského scénáře je formule „Jako [ROLE] chci, aby [CÍL, který má být splněn], protože [výsledná byznysová HODNOTA pro roli]“, doplněná akceptačními kritérii. Formát Given/When/Then se podle 4.5.2 používá pro akceptační kritéria orientovaná na scénáře.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.1","nazev":"Společné psaní uživatelských scénářů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-jedna-spolecne-psani-uzivatelskych-scenaru"}},{"id":"UP-2-29","n":29,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Váš tým používá vývoj řízený akceptačními testy (ATDD) k odvození testovacích případů pro následující uživatelský scénář:<\/p><p><em>Jako zákazník chci mít možnost přizpůsobit si nastavení svého profilu, abych si mohl personalizovat své prostředí na platformě.<\/em><\/p><p>Který z následujících testovacích případů je NEJVHODNĚJŠÍ pro ověření tohoto uživatelského scénáře?<\/p>","m":["<p>Otestovat, zda platforma odesílá e-mailová oznámení o aktualizacích profilu.<\/p>","<p>Otestovat, zda platforma podporuje více jazyků pro přizpůsobení profilu.<\/p>","<p>Otestovat, zda platforma zobrazuje doporučená nastavení na základě preferencí uživatele.<\/p>","<p>Otestovat, zda platforma umožňuje uživatelům změnit si profilový obrázek.<\/p>"],"ok":[3],"vys":{"a":"Není správně. E-mailová oznámení jsou samostatná užitná vlastnost a scénář je nepožaduje.","b":"Není správně. Podpora více jazyků je samostatná užitná vlastnost a nevaliduje přizpůsobení nastavení profilu.","c":"Není správně. Doporučování nastavení je samostatná užitná vlastnost, která přesahuje rámec scénáře.","d":"Je správně. Změna profilového obrázku přímo ověřuje možnost přizpůsobit si nastavení profilu, tedy jádro uživatelského scénáře."},"obecne":"<p>Sylabus 4.5.3: Testovací případy ATDD vycházejí z akceptačních kritérií, musí pokrývat charakteristiky uživatelského scénáře a nemají přesahovat jeho rámec. Přímo ho validuje jen test změny profilového obrázku.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-1-31","n":30,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení platí pro agilní tým?<\/p>","m":["Plány vydání jsou vysokoúrovňové, zatímco plány iterací jsou podrobné.","Plány vydání jsou podrobné, zatímco plány iterací jsou vysokoúrovňové.","Plánování vydání přesně stanovuje předpoklady pro vydání každého přírůstku.","Plánování vydání se zaměřuje na akceptační kritéria, plánování iterace na regresní testy."],"ok":[0],"vys":{"a":"Je správně. Plánování vydání pracuje s produktovým backlogem a hrubě odhadnutými položkami, plánování iterace vyžaduje podrobnou analýzu a podrobnější odhady.","b":"Není správně. Je tomu naopak – při plánování vydání tým ještě podrobně neví, jak položky backlogu implementovat.","c":"Není správně. Plánování vydání vyhlíží dopředu k vydání produktu a pracuje s hrubými odhady; přesné předpoklady pro jednotlivé přírůstky nestanovuje.","d":"Není správně. Plánování iterace se zabývá backlogem iterace, podrobnou analýzou rizik a rozkladem uživatelských scénářů do úkolů, nejen regresními testy."},"obecne":"Sylabus 5.1.2: Plánování vydání vyhlíží dopředu k vydání produktu a definuje a upravuje produktový backlog. Plánování iterace vyhlíží ke konci jedné iterace, pracuje s backlogem iterace a zahrnuje podrobnou analýzu rizik uživatelských scénářů a jejich rozklad do úkolů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"UC-5-24","n":31,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které DVĚ z následujících možností NEJSOU součástí vstupních kritérií pro systémové testování?<\/p><p>i. Dostupnost testovacích dat<br>ii. Všechny smoke testy prošly<br>iii. Bylo provedeno statické testování<br>iv. Počet nevyřešených defektů<br>v. Dostupnost testovací báze<\/p>","m":["<p>ii a v<\/p>","<p>iii a iv<\/p>","<p>i a iv<\/p>","<p>i a iii<\/p>"],"ok":[1],"vys":{"a":"Není správně. Úspěšnost smoke testů (ii) i dostupnost testovací báze (v) jsou typická vstupní kritéria.","b":"Je správně. Provedení statického testování (iii) a počet nevyřešených defektů (iv) sylabus uvádí jako typická výstupní kritéria.","c":"Není správně. Dostupnost testovacích dat (i) je typické vstupní kritérium.","d":"Není správně. Dostupnost testovacích dat (i) je typické vstupní kritérium."},"obecne":"<p>Podle sylabu (kap. 5.1.3) patří mezi typická vstupní kritéria dostupnost zdrojů (např. testovací data), dostupnost testwaru (např. testovací báze) a počáteční úroveň kvality testovaného objektu (např. úspěšnost všech smoke testů) – to jsou možnosti i, ii a v. Naopak „provedení statického testování“ a „počet nevyřešených defektů“ sylabus uvádí jako typická <strong>výstupní<\/strong> kritéria. Vstupními kritérii tedy nejsou iii a iv.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"UC-5-27","n":32,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Tým používá tříbodový odhad včetně chyby měření k odhadu pracnosti testování potřebné pro novou funkci. Tým expertů dospěl k následujícím odhadům:<\/p><p>• nejoptimističtější odhad: 6 člověko-hodin<\/p><p>• nejpravděpodobnější odhad: 12 člověko-hodin<\/p><p>• nejpesimističtější odhad: 18 člověko-hodin<\/p><p>Jaký je výsledný odhad?<\/p>","m":["<p>mezi 9 a 11 člověko-hodinami<\/p>","<p>mezi 11 a 13 člověko-hodinami<\/p>","<p>mezi 10 a 14 člověko-hodinami<\/p>","<p>mezi 13 a 15 člověko-hodinami<\/p>"],"ok":[2],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.1.4) umožňuje tříbodový odhad vypočítat chybu měření ve formě směrodatné odchylky SD = (b - a) / 6.<\/p><p>E = (6 + 4 * 12 + 18) / 6 = 12; SD = (18 - 6) / 6 = 2. Výsledný odhad je tedy 12 ± 2 člověko-hodin, tj. <strong>mezi 10 a 14 člověko-hodinami<\/strong>.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UC-5-43","n":33,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Dostali jste ke spuštění následující sadu testovacích případů. Máte je spouštět v pořadí podle rizika a provést testování co nejrychleji, abyste vývojářům co nejdříve poskytli zpětnou vazbu. Testovací případ lze spustit až po testovacím případu, na kterém závisí.<\/p><table><thead><tr><th>ID testovacího případu<\/th><th>Doba trvání<\/th><th>Priorita rizika<\/th><th>Závisí na<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>30 min<\/td><td>nízká<\/td><td>6<\/td><\/tr><tr><td>2<\/td><td>10 min<\/td><td>střední<\/td><td>–<\/td><\/tr><tr><td>3<\/td><td>45 min<\/td><td>vysoká<\/td><td>1<\/td><\/tr><tr><td>4<\/td><td>30 min<\/td><td>vysoká<\/td><td>2<\/td><\/tr><tr><td>5<\/td><td>10 min<\/td><td>střední<\/td><td>4<\/td><\/tr><tr><td>6<\/td><td>15 min<\/td><td>nízká<\/td><td>2<\/td><\/tr><\/tbody><\/table><p>Jaké je na základě těchto informací NEJLEPŠÍ pořadí spuštění testů?<\/p>","m":["<p>6, 1, 3, 2, 4, 5<\/p>","<p>4, 3, 2, 5, 6, 1<\/p>","<p>2, 5, 6, 4, 1, 3<\/p>","<p>2, 4, 5, 6, 1, 3<\/p>"],"ok":[3],"vys":{"a":"Není správně. Test 6 závisí na testu 2, nemůže tedy být spuštěn jako první.","b":"Není správně. Test 4 závisí na testu 2, nemůže tedy být spuštěn jako první.","c":"Není správně. Test 5 závisí na testu 4, nemůže tedy být spuštěn před ním.","d":"Je správně. Jako jediné respektuje všechny závislosti a vždy spouští test s nejvyšším rizikem z těch, které už lze spustit (2, pak 4, pak 5, a nakonec řetězec 6, 1, 3)."},"obecne":"<p>Sylabus 5.1.5: testovací případy se řadí podle priority (zde podle rizika), ale závislosti mají přednost – test, na kterém jiný test závisí, musí proběhnout dříve. Jako první lze spustit pouze test 2; poté test 4 (vysoké riziko), následně test 5 a nakonec řetězec 6 → 1 → 3, protože vysoce rizikový test 3 vyžaduje testy 6 a 1. Pořadí 2, 4, 5, 6, 1, 3 je jediné z nabízených, které všechny závislosti splňuje.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-6-33","n":34,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Jak souvisejí testovací kvadranty s různými úrovněmi testování (např. testováním komponent, integračním testováním, systémovým testováním a akceptačním testováním)?<\/p>","m":["<p>Kvadranty seskupují úrovně testování s vhodnými typy testů a činnostmi.<\/p>","<p>Kvadranty s úrovněmi testování nijak nesouvisejí a používají se samostatně.<\/p>","<p>Kvadranty představují postupné fáze procesu testování, které jdou za sebou.<\/p>","<p>Každý kvadrant odpovídá právě jedné konkrétní úrovni testování.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Kvadranty seskupují úrovně testování s vhodnými typy testů, činnostmi, technikami testování a pracovními produkty a ukazují, že některé typy testů jsou pro určité úrovně relevantnější.","b":"Není správně. Model kvadrantů úrovně testování výslovně seskupuje s typy testů, nejsou na sobě nezávislé.","c":"Není správně. Kvadranty nejsou fáze ani posloupnost; testy z různých kvadrantů mohou probíhat souběžně.","d":"Není správně. Kvadrant může zahrnovat testy z více úrovní testování; např. Q1 obsahuje testy komponent i integrační testy komponent."},"obecne":"Sylabus 5.1.7: Testovací kvadranty seskupují úrovně testování s vhodnými typy testů, činnostmi, technikami testování a pracovními produkty. Pomáhají zajistit, aby byly v SDLC zahrnuty všechny vhodné typy testů a úrovně testování, a ukazují, že některé typy testů jsou pro určité úrovně testování relevantnější než jiné.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"UC-5-30","n":35,"lo":"FL-5.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> cílem analýzy produktových rizik z hlediska testování?<\/p>","m":["<p>Stanovit priority testování s cílem nalézt kritické defekty co nejdříve<\/p>","<p>Zajistit, aby po vydání nezůstalo žádné reziduální produktové riziko<\/p>","<p>Nasměrovat úsilí při testování tak, aby došlo k minimalizaci reziduální úrovně produktových rizik<\/p>","<p>Poskytnout povědomí o produktových rizicích<\/p>"],"ok":[1],"vys":{},"obecne":"Sylabus 5.2.3: Z hlediska testování je cílem analýzy produktových rizik poskytnout povědomí o produktových rizicích a nasměrovat úsilí při testování tak, aby se minimalizovala reziduální úroveň produktových rizik; její výsledky se mj. používají ke stanovení priorit testování s cílem nalézt kritické defekty co nejdříve. Produktové riziko však testováním nelze úplně odstranit, lze ho jen snížit.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"}},{"id":"UC-5-33","n":36,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Zvažte následující obsah reportů z testování:<\/p><p>i. Nová a změněná rizika během testovacího období<br>ii. Neošetřená rizika, nevyřešené defekty<br>iii. Postup prací při testování včetně všech významných odchylek<br>iv. Ponaučení (lessons learned), která jsou relevantní pro testování<\/p><p>Které z nich patří do reportu o postupu prací při testování a které do souhrnného reportu z testování?<\/p>","m":["<p>ii a iii jsou součástí reportu o postupu prací při testování, zatímco i a iv jsou součástí souhrnného reportu z testování.<\/p>","<p>i a iv jsou součástí reportu o postupu prací při testování, zatímco iii a iv jsou součástí souhrnného reportu z testování.<\/p>","<p>i a iii jsou součástí reportu o postupu prací při testování, zatímco ii a iv jsou součástí souhrnného reportu z testování.<\/p>","<p>i a ii jsou součástí reportu o postupu prací při testování, zatímco iii a iv jsou součástí souhrnného reportu z testování.<\/p>"],"ok":[2],"vys":{},"obecne":"Sylabus 5.3.2: Report o postupu prací při testování obsahuje mj. postup prací při testování včetně všech významných odchylek (iii) a nová a změněná rizika během testovacího období (i). Souhrnný report z testování obsahuje mj. neošetřená rizika a nevyřešené defekty (ii) a ponaučení (lessons learned), která jsou relevantní pro testování (iv).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-3-37","n":37,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Pokud vývojáři předávají k testování kód, který není pod správou verzí, jaký proces chybí?<\/p>","m":["<p>Analýza rizik<\/p>","<p>Management defektů<\/p>","<p>Ladění<\/p>","<p>Konfigurační management<\/p>"],"ok":[3],"vys":{"a":"Není správně. Analýza rizik zahrnuje identifikaci a ohodnocení rizik, nikoli správu verzí.","b":"Není správně. Management defektů řeší zpracování anomálií a defektů od nahlášení po uzavření.","c":"Není správně. Ladění je hledání a oprava příčin selhání v kódu, se správou verzí nesouvisí.","d":"Je správně. Konfigurační management zajišťuje jednoznačnou identifikaci a řízení verzí všech konfiguračních položek včetně testovaného objektu."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky včetně testovaného objektu jsou jednoznačně identifikovány, jejich verze řízeny a změny evidovány. Pokud kód předávaný k testování není pod správou verzí, chybí právě tento proces.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-6-38","n":38,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Provádíte systémové testování systému pro rezervaci vlakových jízdenek a zjistili jste, že systém občas hlásí, že nejsou k dispozici žádné vlaky, ačkoli podle testovacích případů, které jste spustili, by k dispozici být měly. Vedoucímu vývoje jste poskytli shrnutí defektu a verzi testovaného systému. Vývojáři si uvědomují naléhavost defektu a nyní čekají, až jim poskytnete další podrobnosti, aby ho mohli opravit.<\/p><p>Jsou dány následující informace:<\/p><ol><li><p>Míra dopadu (závažnost) defektu<\/p><\/li><li><p>Identifikace položky testování<\/p><\/li><li><p>Podrobnosti o testovacím prostředí<\/p><\/li><li><p>Naléhavost/priorita opravy<\/p><\/li><li><p>Skutečné výsledky<\/p><\/li><li><p>Odkaz na specifikaci testovacího případu<\/p><\/li><\/ol><p>Které z těchto informací by bylo kromě popisu defektu, který obsahuje výpis databáze a snímky obrazovky, NEJUŽITEČNĚJŠÍ uvést v prvotním reportu o defektu?<\/p>","m":["<p>3, 5, 6<\/p>","<p>1, 2, 6<\/p>","<p>1, 4, 5, 6<\/p>","<p>2, 3, 4, 5<\/p>"],"ok":[0],"vys":{"a":"Je správně. Podrobnosti o testovacím prostředí, skutečné výsledky a odkaz na testovací případ (vstupy a očekávané výsledky) vývojářům nejvíce pomohou občasné selhání reprodukovat a opravit.","b":"Není správně. Závažnost (1) i identifikaci položky testování (2) už vývojáři znají; chybí podrobnosti o prostředí (3) a skutečné výsledky (5).","c":"Není správně. Závažnost (1) a priorita (4) jsou vývojářům známé – naléhavost defektu už sami uznali; chybí podrobnosti o testovacím prostředí (3).","d":"Není správně. Identifikace položky (2) a priorita (4) jsou již známé; chybí odkaz na specifikaci testovacího případu (6) se vstupy a očekávanými výsledky."},"obecne":"Sylabus 5.5: Report o defektu má poskytnout dostatek informací k vyřešení problému. Vývojáři už znají verzi systému (identifikaci položky testování) a defekt považují za naléhavý, takže závažnost a priorita pro ně nejsou nové. K reprodukci občasného selhání nejvíce potřebují podrobnosti o testovacím prostředí (3), skutečné výsledky (5) a odkaz na testovací případ se vstupy a očekávanými výsledky (6).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"TR-077","n":39,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"Do které kategorie testovacích nástrojů patří nástroj pro statickou analýzu kódu?","m":["Nástroje DevOps","Nástroje pro statické testování","Nástroje pro management testování","Nástroje pro nefunkcionální testování"],"ok":[1],"vys":{"a":"Není správně. Nástroje DevOps podporují pipeline, automatizované sestavování a CI/CD.","b":"Je správně. Nástroje pro statické testování podporují provádění revizí a statické analýzy.","c":"Není správně. Nástroje pro management testování usnadňují správu požadavků, testů, defektů a konfigurací.","d":"Není správně. Nástroje pro nefunkcionální testování umožňují např. zátěžové testování, které nelze provést manuálně."},"obecne":"Sylabus 6.1: nástroje pro statické testování podporují provádění revizí a statické analýzy. Nástroj pro statickou analýzu kódu proto patří do této kategorie.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-5-40","n":40,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je NEJPRAVDĚPODOBNĚJI přínosem nástrojů pro provádění testů?<\/p>","m":["<p>Snadná správa verzí testwaru.<\/p>","<p>Snadný návrh testů zabezpečení.<\/p>","<p>Snadné spouštění regresních testů.<\/p>","<p>Snadné vytváření regresních testů.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Správu verzí zajišťuje konfigurační management, ne nástroj pro provádění testů.","b":"Není správně. Návrh testů zabezpečení nástroj pro provádění testů nepodporuje.","c":"Je správně. Snížení opakované manuální práce, např. spouštění regresních testů, je přínosem automatizace.","d":"Není správně. Přínos se projevuje při opakovaném provádění regresních testů, ne při jejich vytváření."},"obecne":"Sylabus 6.2: přínosem automatizace je úspora času snížením opakované manuální práce, např. provádění regresních testů, opakované zadávání stejných testovacích dat nebo porovnávání očekávaných a skutečných výsledků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}}]};
